export function createDocument(title, content) {
  return {
    title,
    content,
    fields: {
      title: createFieldIndex(title),
      content: createFieldIndex(content),
    },
  };
}

function matchTerm(field, term) {
  return field.termSet.has(term);
}

function matchWildcard(field, regex) {
  return field.terms.some((term) => regex.test(term));
}

function matchPhrase(field, terms) {
  if (terms.length === 0) {
    return false;
  }

  for (let index = 0; index <= field.terms.length - terms.length; index += 1) {
    let matched = true;

    for (let offset = 0; offset < terms.length; offset += 1) {
      if (field.terms[index + offset] !== terms[offset]) {
        matched = false;
        break;
      }
    }

    if (matched) {
      return true;
    }
  }

  return false;
}

function matchRange(field, node) {
  return field.terms.some((term) => {
    if (node.start !== null) {
      const startOk = node.startInclusive ? term >= node.start : term > node.start;

      if (!startOk) {
        return false;
      }
    }

    if (node.end !== null) {
      const endOk = node.endInclusive ? term <= node.end : term < node.end;

      if (!endOk) {
        return false;
      }
    }

    return true;
  });
}

export function matchesDocument(document, query) {
  switch (query.type) {
    case "null":
      return false;
    case "term":
      return matchTerm(document.fields[query.field], query.term);
    case "wildcard":
      return matchWildcard(document.fields[query.field], query.regex);
    case "phrase":
      return matchPhrase(document.fields[query.field], query.terms);
    case "range":
      return matchRange(document.fields[query.field], query);
    case "and":
      return query.children.every((child) => matchesDocument(document, child));
    case "or":
      return query.children.some((child) => matchesDocument(document, child));
    case "not":
      return !matchesDocument(document, query.child);
    default:
      return false;
  }
}

export function searchDocuments(documents, query) {
  let count = 0;

  for (const document of documents) {
    if (matchesDocument(document, query)) {
      count += 1;
    }
  }

